        "aalborg-smi": { "why": "Studies human sensory-motor integration and develops neurorehabilitation, pain, stimulation, and assistive technologies. Based at Aalborg University in Aalborg, Denmark, this center is distinctive for connecting motor control, pain, and rehabilitation within one research effort.", "methods": "Primary approaches: Motor control; Pain; Rehabilitation. Linked tools and modalities: EMG and peripheral gesture interfaces (motor-unit activity in muscle / nerve; forearm or residual limb); Functional electrical stimulation (motor-nerve / muscle stimulation; muscle or nerve territory); Peripheral nerve interfaces (fascicular motor and sensory traffic; nerve / fascicle / axon bundle).", "evidenceLabel": "Official center or institutional page — Center for Sensory-Motor Interaction (smi.hst.aau.dk)" },
        "santanna": { "why": "Creates wearable and implantable bionic systems, neuroprostheses, rehabilitation robots, and sensory feedback technologies. Based at Scuola Superiore Sant'Anna in Pisa, Italy, this institute is distinctive for connecting bionic limbs, robotics, and sensory feedback within one research effort.", "methods": "Primary approaches: Bionic limbs; Robotics; Sensory feedback. Linked tools and modalities: Bidirectional bionic hand (eMG / nerve intent <-> tactile feedback; multi-DOF hand and nerve fascicles); Peripheral nerve interfaces (fascicular motor and sensory traffic; nerve / fascicle / axon bundle); EMG and peripheral gesture interfaces (motor-unit activity in muscle / nerve; forearm or residual limb).", "evidenceLabel": "Official institute or institutional page — The BioRobotics Institute (santannapisa.it)" },
        "ibec": { "why": "Bioengineering institute with work on neural systems, biomaterials, organ-on-chip platforms, imaging, and regenerative medicine. Based at IBEC in Barcelona, Spain, this institute is distinctive for connecting bioengineering, neuroengineering, and brain-on-chip within one research effort.", "methods": "Primary approaches: Bioengineering; Neuroengineering; Brain-on-chip. Linked tools and modalities: Brain organoids and assembloids (developing human neural tissue activity; cellular / organoid-scale); Living and biohybrid neural interfaces (host <-> engineered neural tissue; cellular biological bridge); Neural scaffolds, hydrogels and cell grafts (biochemical and mechanical repair cues; lesion / tract scale).", "evidenceLabel": "Official institute or institutional page — Institute for Bioengineering of Catalonia (ibecbarcelona.eu)" },
        "riken-cbs": { "why": "Japan's major multidisciplinary brain center, spanning molecules and cells through circuits, behavior, computation, and technology development. Based at RIKEN in Wako, Japan, this institute is distinctive for connecting circuit tools, brain models, and neurotechnology within one research effort.", "methods": "Primary approaches: Circuit tools; Brain models; Neurotechnology. Linked tools and modalities: Calcium imaging / GCaMP (calcium transients as activity proxy; cellular to mesoscale); Optogenetics (light-gated cell activity; cell-type / projection specificity); Multiscale circuit models and digital twins (anatomy + physiology + behavior -> simulation; ion channel to whole-brain network).", "evidenceLabel": "Official institute or institutional page — RIKEN Center for Brain Science (riken.jp)" },
        "atr-bicr": { "why": "Develops brain decoding, brain-machine interfaces, neurofeedback, robotics, and computational approaches to cognition. Based at ATR in Keihanna, Japan, this institute is distinctive for connecting brain decoding, bMI, and decoded neurofeedback within one research effort.", "methods": "Primary approaches: Brain decoding; BMI; Decoded neurofeedback. Linked tools and modalities: BOLD fMRI (blood oxygenation response; sub-mm to few-mm); EEG / fNIRS neurofeedback (brain-derived metric -> feedback; network / band-power proxy); Motor BCI for cursor and robotics (motor intent -> device commands; population-level decoder).", "evidenceLabel": "Official institute or institutional page — Brain Information Communication Research Laboratory Group (bicr.atr.jp)" },
        "oist-ncu": { "why": "Studies neural computation, learning, and adaptive behavior using theory, experiments, and robotics. Based at Okinawa Institute of Science and Technology in Onna, Japan, this lab is distinctive for connecting computational, reinforcement learning, and robotics within one research effort.", "methods": "Primary approaches: Computational; Reinforcement learning; Robotics. Linked tools and modalities: Adaptive neural decoders (population activity -> latent intent / state; task-dependent); Neuromorphic neural coprocessors (spikes / biomarkers -> low-power inference; implant or wearable edge compute); Multiscale circuit models and digital twins (anatomy + physiology + behavior -> simulation; ion channel to whole-brain network).", "evidenceLabel": "Official lab or institutional page — Neural Computation Unit (oist.jp)" },
