        "siat-bcbdi": { "why": "Institute spanning development, degeneration, brain-body interaction, brain-computer interfaces, and preclinical-to-clinical translation. Based at Shenzhen Institutes of Advanced Technology, CAS in Shenzhen, China, this institute is distinctive for connecting bCI, brain disease, and clinical translation within one research effort.", "methods": "Primary approaches: BCI; Brain disease; Clinical translation. Linked tools and modalities: Motor BCI for cursor and robotics (motor intent -> device commands; population-level decoder); Deep brain stimulation (electrical pulses to deep networks; mm-scale volume of tissue activated); Cell census and spatial omics (rNA, epigenome, morphology and location; single-cell to spatial tissue maps).", "evidenceLabel": "Official institute or institutional page — Brain Cognition and Brain Disease Institute (isynbio.siat.ac.cn)" },
        "hkust-cce": { "why": "Models brain adaptation and develops learning-based brain-machine and neuroprosthetic control systems. Based at Hong Kong University of Science and Technology in Hong Kong, China, this lab is distinctive for connecting bMI, neural adaptation, and neuroprosthetics within one research effort.", "methods": "Primary approaches: BMI; Neural adaptation; Neuroprosthetics. Linked tools and modalities: Motor BCI for cursor and robotics (motor intent -> device commands; population-level decoder); Adaptive neural decoders (population activity -> latent intent / state; task-dependent); EMG and peripheral gesture interfaces (motor-unit activity in muscle / nerve; forearm or residual limb).", "evidenceLabel": "Official lab or institutional page — Computational Cognitive Engineering Lab (bmi.hkust.edu.hk)" },
        "polyu-bmi": { "why": "Develops neural decoding, stimulation, robotic exoskeletons, and sensory-feedback systems for rehabilitation and prosthetics. Based at Hong Kong Polytechnic University in Hong Kong, China, this program is distinctive for connecting neuroprosthetics, robotic rehabilitation, and stimulation within one research effort.", "methods": "Primary approaches: Neuroprosthetics; Robotic rehabilitation; Stimulation. Linked tools and modalities: Motor BCI for cursor and robotics (motor intent -> device commands; population-level decoder); Cortical sensory feedback BCI (robot / sensor data -> ICMS percepts; somatotopic microelectrodes); Functional electrical stimulation (motor-nerve / muscle stimulation; muscle or nerve territory).", "evidenceLabel": "Official program or institutional page — Brain-Machine Interface and Neural Engineering (polyu.edu.hk)" },
        "ntu-cbcr": { "why": "Advances EEG and fNIRS decoding, BCI rehabilitation, cognitive-state monitoring, and machine-learning methods. Based at Nanyang Technological University in Singapore, Singapore, this center is distinctive for connecting non-invasive BCI, stroke rehabilitation, and affective computing within one research effort.", "methods": "Primary approaches: Non-invasive BCI; Stroke rehabilitation; Affective computing. Linked tools and modalities: Scalp EEG (summed postsynaptic field potentials; cm-scale scalp topography); fNIRS / diffuse optical imaging (oxy- and deoxyhemoglobin; cm-scale superficial cortex); Motor BCI for cursor and robotics (motor intent -> device commands; population-level decoder).", "evidenceLabel": "Official center or institutional page — Centre for Brain-Computing Research (ntu.edu.sg)" },
